import { test, expect } from '@playwright/test';

test.describe('Async State Preservation During Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('data:text/html,<html><body><div id="app"></div><script>window.appState = { counter: 0, loading: false };</script></body></html>');
  });

  test('should preserve async state when navigating to another page', async ({ page }) => {
    // Set up initial async state
    await page.evaluate(() => {
      window.appState = { counter: 5, loading: false, data: 'test' };
    });

    // Verify initial state is set
    const initialState = await page.evaluate(() => window.appState);
    expect(initialState.counter).toBe(5);
    expect(initialState.data).toBe('test');

    // Navigate to a new page
    await page.goto('data:text/html,<html><body><div id="app"></div><script>window.appState = { counter: 0, loading: false };</script></body></html>');

    // State should be reset on new page
    const newPageState = await page.evaluate(() => window.appState);
    expect(newPageState.counter).toBe(0);
  });

  test('should preserve async state across navigation with session storage', async ({ page }) => {
    // Store async state in session storage before navigation
    await page.evaluate(() => {
      const asyncState = { counter: 10, loading: false, timestamp: Date.now() };
      sessionStorage.setItem('appAsyncState', JSON.stringify(asyncState));
      window.appState = asyncState;
    });

    // Verify state is stored
    const storedState = await page.evaluate(() => JSON.parse(sessionStorage.getItem('appAsyncState')));
    expect(storedState.counter).toBe(10);

    // Navigate to another page
    await page.goto('data:text/html,<html><body><div id="app"></div><script>const stored = sessionStorage.getItem("appAsyncState"); if(stored) { window.appState = JSON.parse(stored); } else { window.appState = { counter: 0 }; }</script></body></html>');

    // Verify async state is preserved from session storage
    const preservedState = await page.evaluate(() => window.appState);
    expect(preservedState.counter).toBe(10);
    expect(preservedState.timestamp).toBeDefined();
  });

  test('should handle async operations during navigation', async ({ page }) => {
    // Set up async operation that stores state
    await page.evaluate(() => {
      window.asyncOperation = async () => {
        return new Promise((resolve) => {
          setTimeout(() => {
            window.appState = { counter: 15, loading: false, completed: true };
            sessionStorage.setItem('operationResult', JSON.stringify(window.appState));
            resolve(window.appState);
          }, 100);
        });
      };
    });

    // Execute async operation
    const result = await page.evaluate(() => window.asyncOperation());
    expect(result.counter).toBe(15);
    expect(result.completed).toBe(true);

    // Verify state is persisted in session storage
    const persistedState = await page.evaluate(() => JSON.parse(sessionStorage.getItem('operationResult')));
    expect(persistedState.counter).toBe(15);

    // Navigate and restore state
    await page.goto('data:text/html,<html><body><div id="app"></div><script>const result = sessionStorage.getItem("operationResult"); window.appState = result ? JSON.parse(result) : { counter: 0 };</script></body></html>');

    // Verify state is restored after navigation
    const restoredState = await page.evaluate(() => window.appState);
    expect(restoredState.counter).toBe(15);
    expect(restoredState.completed).toBe(true);
  });

  test('should maintain async state consistency across multiple navigations', async ({ page }) => {
    // Initialize state with async data
    await page.evaluate(() => {
      window.appState = { version: 1, data: 'initial', timestamp: Date.now() };
      localStorage.setItem('appStateVersion', '1');
    });

    // First navigation
    await page.goto('data:text/html,<html><body><div id="app"></div><script>const version = localStorage.getItem("appStateVersion"); window.appState = { version: parseInt(version || "0"), data: "updated" };</script></body></html>');

    let currentState = await page.evaluate(() => window.appState);
    expect(currentState.version).toBe(1);

    // Update state
    await page.evaluate(() => {
      window.appState.version = 2;
      localStorage.setItem('appStateVersion', '2');
    });

    // Second navigation
    await page.goto('data:text/html,<html><body><div id="app"></div><script>const version = localStorage.getItem("appStateVersion"); window.appState = { version: parseInt(version || "0"), data: "final" };</script></body></html>');

    currentState = await page.evaluate(() => window.appState);
    expect(currentState.version).toBe(2);
  });
});
